const rows = $input.all().map(item => item.json).filter(row => {
return row && Object.values(row).some(v => v !== null && v !== undefined && String(v).trim() !== '');
});

if (!rows.length) {
return [];
}

const CONFIG = {
currentSheetName: 'QA_Resultados',
historicalSheetName: 'QA_Historico',
slackChannel: '#cx-team',
nameMap: {
'Agent1': 'Agent1',
'Agent2': 'Agent2',
'Agent3': 'Agent3',
'Agent4': 'Agent4',
'Agent5': 'Agent5',
},
};

const specialistKey = 'CX Specialist';
const scoreKey = 'Score';
const feedbackKey = 'Feedback';

const ignoredKeys = new Set([
'Timestamp',
'Email Address',
'Conversation ID',
'Interaction Date',
'Proceso',
'Sub Proceso',
'Detalle Proceso',
feedbackKey,
scoreKey,
specialistKey,
]);

const allKeys = Object.keys(rows[0] || {});
const autofailKeys = allKeys.filter(k => String(k).includes('Autofails'));

const shouldExcludeCriterion = (key) => {
const lower = String(key || '').toLowerCase();
return lower.includes('tiempo menor o igual a 5 minutos') || lower.includes('tiempo de respuesta');
};

const criteriaKeys = allKeys.filter(k =>
!ignoredKeys.has(k) &&
!String(k).includes('Autofails') &&
!shouldExcludeCriterion(k)
);

const simplifyCriterion = (key) => {
let clean = String(key || '')
.replace(/^¿/, '')
.replace(/\s+/g, ' ')
.trim();

if (clean.endsWith('?')) {
clean = clean.slice(0, -1);
}

const lower = clean.toLowerCase();

if (lower.includes('filtros del caso') || lower.includes('user id')) return 'Filtros de chat';
if (lower.includes('macro')) return 'Uso de macro';
if (lower.includes('revisó y consideró toda la información')) return 'Revisión de contexto';
if (lower.includes('empático')) return 'Empatía';
if (lower.includes('saluda') || lower.includes('branding')) return 'Saludo y branding';
if (lower.includes('preguntas')) return 'Sondeo y preguntas';
if (lower.includes('resolvió')) return 'Resolución correcta';
if (lower.includes('redactó')) return 'Redacción';
if (lower.includes('ticket')) return 'Creación de ticket';
if (lower.includes('protocolo')) return 'Aplicación de protocolo';
if (lower.includes('ayuda adicional')) return 'Ayuda adicional';
if (lower.includes('cerró')) return 'Cierre de chat';

return clean;
};

const normalizeAgent = (name) => {
const clean = String(name || '').trim();
return CONFIG.nameMap[clean] || clean;
};

const parseScore = (value) => {
if (!value) return 0;
const raw = String(value).replace('%', '').replace(',', '.').trim();
let num = Number(raw);
if (!Number.isFinite(num)) return 0;
if (num > 0 && num <= 1) num = num * 100;
return num;
};

const totalInteractions = rows.length;
const scores = rows.map(r => parseScore(r[scoreKey]));
const avgScore = scores.reduce((acc, n) => acc + n, 0) / (scores.length || 1);

const criterionStats = criteriaKeys.map(key => {
const incorrect = rows.filter(r => String(r[key] || '').includes('❌')).length;
return {
label: simplifyCriterion(key),
incorrect,
percent: totalInteractions ? (incorrect / totalInteractions) * 100 : 0,
};
}).filter(c => c.incorrect > 0)
.sort((a, b) => b.incorrect - a.incorrect);

const totalIncorrect = criterionStats.reduce((acc, c) => acc + c.incorrect, 0);

const uniqueAgents = [...new Set(rows.map(r => normalizeAgent(r[specialistKey])).filter(Boolean))];
const auditsPerAgent = uniqueAgents.length ? (totalInteractions / uniqueAgents.length) : totalInteractions;

const topCriteria = criterionStats.slice(0, 3);

const agentBlocks = uniqueAgents.map(agent => {
const agentRows = rows.filter(r => normalizeAgent(r[specialistKey]) === agent);
const localStats = criteriaKeys.map(key => {
const incorrect = agentRows.filter(r => String(r[key] || '').includes('❌')).length;
return {
label: simplifyCriterion(key),
incorrect,
percent: agentRows.length ? (incorrect / agentRows.length) * 100 : 0,
};
}).sort((a, b) => b.incorrect - a.incorrect);

const main = localStats[0] && localStats[0].incorrect > 0 ? localStats[0] : null;

return { agent, main };
});

const autofails = [];
for (const row of rows) {
const agent = normalizeAgent(row[specialistKey]);
for (const key of autofailKeys) {
const value = String(row[key] || '').trim();
if (value && !value.includes('✅')) {
autofails.push({
agent,
criterion: simplifyCriterion(key),
});
}
}
}

const scoreEmoji = avgScore >= 95 ? '🟢' : avgScore >= 90 ? '🟡' : '🔴';
const opportunityEmoji = totalIncorrect <= Math.max(2, totalInteractions * 0.15)
? '🟢'
: totalIncorrect <= Math.max(5, totalInteractions * 0.3)
? '🟡'
: '🔴';

const tip = (label) => {
const l = label.toLowerCase();
if (l.includes('filtros')) return 'Valida tipificación y User ID antes de cerrar.';
if (l.includes('macro')) return 'Confirma que la macro aplica al caso.';
if (l.includes('contexto')) return 'Revisa todo el historial antes de responder.';
if (l.includes('empatía')) return 'Reconoce el contexto del usuario primero.';
return 'Refuerza este punto antes de cerrar.';
};

const topCriteriaText = topCriteria.map(c =>
`• *${c.label}* — ${c.percent.toFixed(1)}%\n  :wrench: _${tip(c.label)}_`
).join('\n\n');

const agentImpactText = agentBlocks.map(b =>
b.main
? `• *${b.agent}* — ${b.main.label} (${b.main.percent.toFixed(1)}%)\n  :wrench: _${tip(b.main.label)}_`
: `• *${b.agent}* — sin oportunidades críticas`
).join('\n\n');

const autofailsText = autofails.length
? autofails.map(a => `• *${a.agent}*: ${a.criterion}`).join('\n')
: '• No se identificaron auto fails.';

const bogotaNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const day = bogotaNow.getDay();
const diffToMonday = day === 0 ? 6 : day - 1;

const currentMonday = new Date(bogotaNow);
currentMonday.setDate(bogotaNow.getDate() - diffToMonday);

const previousMonday = new Date(currentMonday);
previousMonday.setDate(currentMonday.getDate() - 7);

const previousSunday = new Date(previousMonday);
previousSunday.setDate(previousMonday.getDate() + 6);

const formatDate = (d) => d.toLocaleDateString('es-CO', {
timeZone: 'America/Bogota',
day: 'numeric',
month: 'long',
year: 'numeric',
});

const weekRange = `${formatDate(previousMonday)} al ${formatDate(previousSunday)}`;

const reportDateShort = bogotaNow.toLocaleDateString('en-US', {
timeZone: 'America/Bogota',
month: '2-digit',
day: '2-digit',
});

const slackText = `:bar_chart: *Resultados última semana:*
:date: *Semana evaluada:* ${weekRange}

*QA Score:* ${avgScore.toFixed(2)}% ${scoreEmoji}

*Oportunidades:* ${totalIncorrect} ${opportunityEmoji}

*Auditorías:* ${totalInteractions} (${auditsPerAgent.toFixed(1)} por agente)

:triangular_flag_on_post: *Top oportunidades*
${topCriteriaText}

:busts_in_silhouette: *Foco principal por agente*
${agentImpactText}

:rotating_light: *Autofails*
${autofailsText}

No olviden dejar su reacción para confirmar que dieron una ojeada por acá.

cc. <!subteam^S042S3Z88KS>`;

return [{
json: {
slackText,
rowCount: totalInteractions,
weekRange,
totalInteractions,
avgScore: Number(avgScore.toFixed(2)),
totalIncorrect,
slackChannel: CONFIG.slackChannel,
currentSheetName: CONFIG.currentSheetName,
historicalSheetName: CONFIG.historicalSheetName,
reportDateShort,
}
}];
